import QRCode from 'qrcode'
import { el } from '../dom.js'
import { proofUrl } from '../flex.js'

export async function showQrModal(bundle) {
  const url = proofUrl(bundle)
  const qr = await QRCode.toDataURL(url, { width: 520, margin: 1, color: { dark: '#111111', light: '#ffffff' } })
  const copyBtn = el('button', {
    onclick: () => { navigator.clipboard.writeText(url); copyBtn.textContent = 'Copied!' },
  }, 'Copy link')
  const overlay = el('div', { class: 'modal', onclick: () => overlay.remove() },
    el('div', { class: 'sheet', onclick: (e) => e.stopPropagation() },
      el('img', { src: qr, alt: 'Verified Flex QR' }),
      el('div', { class: 't' }, 'Verified Flex'),
      el('div', { class: 's' }, 'Scan to verify this NFT is hardware-owned'),
      copyBtn))
  document.body.append(overlay)
}
