import { el, replace } from '../dom.js'
import { pruneProofs, fmtLeft } from '../flex.js'
import { showQrModal } from './modal.js'

export function renderProofs(container) {
  const now = Math.floor(Date.now() / 1000)
  const proofs = pruneProofs()
  if (!proofs.length) return replace(container)
  replace(container,
    el('h2', {}, `Active proofs — ${proofs.filter((f) => f.expiresAt > now).length}`),
    el('div', { class: 'prooflist' }, proofs.map((f) => {
      const expired = f.expiresAt <= now
      return el('div', { class: expired ? 'proofrow expired' : 'proofrow' },
        el('span', { style: 'flex:1' }, el('b', {}, f.name), ` · ${f.chainName}`),
        el('span', { class: expired ? 'left bad' : 'left' }, fmtLeft(f.expiresAt - now)),
        !expired && el('button', { class: 'ghost', onclick: () => showQrModal(f.bundle) }, 'QR'))
    })))
}
