// DisplayAuthorization typed-data construction and the independently computed
// digests shown to the user for comparison with the KeepKey screen (SPEC.md).
import { keccak256, encodeAbiParameters, stringToBytes } from 'viem'
import { AUTH_TYPES, EIP712_DOMAIN_NAME, EIP712_DOMAIN_VERSION } from './config.js'

export const buildTypedData = (chainId, message) => ({
  types: {
    EIP712Domain: [
      { name: 'name', type: 'string' }, { name: 'version', type: 'string' }, { name: 'chainId', type: 'uint256' },
    ],
    ...AUTH_TYPES,
  },
  primaryType: 'DisplayAuthorization',
  domain: { name: EIP712_DOMAIN_NAME, version: EIP712_DOMAIN_VERSION, chainId },
  message,
})

const DOMAIN_TYPEHASH = keccak256(stringToBytes('EIP712Domain(string name,string version,uint256 chainId)'))
const AUTH_TYPEHASH = keccak256(stringToBytes(
  'DisplayAuthorization(address nftContract,uint256 tokenId,bytes32 deviceId,bytes32 nonce,bytes32 imageHash,uint64 issuedAt,uint64 expiresAt)'))

export function digests(chainId, m) {
  const domainSep = keccak256(encodeAbiParameters(
    [{ type: 'bytes32' }, { type: 'bytes32' }, { type: 'bytes32' }, { type: 'uint256' }],
    [DOMAIN_TYPEHASH, keccak256(stringToBytes(EIP712_DOMAIN_NAME)), keccak256(stringToBytes(EIP712_DOMAIN_VERSION)), BigInt(chainId)]))
  const structHash = keccak256(encodeAbiParameters(
    [{ type: 'bytes32' }, { type: 'address' }, { type: 'uint256' }, { type: 'bytes32' }, { type: 'bytes32' }, { type: 'bytes32' }, { type: 'uint64' }, { type: 'uint64' }],
    [AUTH_TYPEHASH, m.nftContract, BigInt(m.tokenId), m.deviceId, m.nonce, m.imageHash, BigInt(m.issuedAt), BigInt(m.expiresAt)]))
  return { domainSep, structHash }
}
