// Safe DOM construction. THE security invariant of this codebase:
// untrusted strings (NFT names, metadata, API responses) only ever enter the
// DOM as text nodes via el()/text — never as markup. `innerHTML` must not
// appear anywhere in src/ (auditable with: grep -r innerHTML src/).

export const $ = (id) => document.getElementById(id)

export function el(tag, attrs = {}, ...children) {
  const node = document.createElement(tag)
  for (const [k, v] of Object.entries(attrs)) {
    if (v === null || v === undefined || v === false) continue
    if (k === 'class') node.className = v
    else if (k === 'dataset') Object.assign(node.dataset, v)
    else if (k.startsWith('on') && typeof v === 'function') node.addEventListener(k.slice(2), v)
    else node.setAttribute(k, String(v))
  }
  for (const c of children.flat(9)) {
    if (c === null || c === undefined || c === false) continue
    node.append(c instanceof Node ? c : document.createTextNode(String(c)))
  }
  return node
}

export function replace(container, ...children) {
  container.replaceChildren(...children.flat(9).filter((c) => c !== null && c !== undefined && c !== false)
    .map((c) => (c instanceof Node ? c : document.createTextNode(String(c)))))
}
