// NFT discovery via keyless Blockscout APIs. Everything returned by these
// endpoints is UNTRUSTED (names, metadata, URLs) — render as text only,
// resolve images defensively.
import { CHAINS, IPFS_GATEWAYS, SPAM } from './config.js'

export const keyOf = (n) => `${n.chainId}:${(n.contract || '').toLowerCase()}:${n.tokenId}`

// Extract an IPFS path from possibly percent-encoded, wrapped URLs and return
// gateway candidates; plain https URLs pass through. Anything else (data:,
// javascript:, ipfs-less garbage) resolves to no image at all.
export function imageCandidates(...urls) {
  for (let u of urls.filter(Boolean)) {
    u = String(u)
    try { u = decodeURIComponent(u) } catch { /* keep raw */ }
    const m = u.match(/ipfs:\/\/([^"'\s&]+)/) || u.match(/\/ipfs\/([^"'\s?&]+)/)
    if (m) return IPFS_GATEWAYS.map((g) => g + m[1])
    if (/^https:\/\//.test(u)) return [u]
  }
  return []
}

export async function scanChain(chain, account, onError) {
  try {
    const r = await fetch(`${chain.scout}/api/v2/addresses/${account.address}/nft?type=ERC-721%2CERC-1155`)
    if (!r.ok) return []
    const { items = [] } = await r.json()
    return items.map((it) => {
      const name = it.metadata?.name || `${it.token?.name || '?'} #${it.id}`
      return {
        chainId: chain.id, chainName: chain.name,
        contract: it.token?.address_hash || it.token?.address,
        tokenId: String(it.id),
        name: String(name).slice(0, 120),
        standard: it.token?.type,
        images: imageCandidates(it.image_url, it.metadata?.image, it.metadata?.image_url),
        attributes: Array.isArray(it.metadata?.attributes) ? it.metadata.attributes.slice(0, 12) : [],
        spam: SPAM.test(it.token?.name || '') || SPAM.test(String(name)),
        owner: account.address, ownerIndex: account.index,
      }
    }).filter((n) => n.contract)
  } catch (e) {
    onError?.(chain, account, e)
    return []
  }
}

export const scanAll = (accounts, onProgress) =>
  Promise.all(accounts.flatMap((a) => CHAINS.map(async (c) => {
    const out = await scanChain(c, a)
    onProgress?.(a, c, out.length)
    return out
  }))).then((r) => r.flat())
