import { el, replace } from '../dom.js'
import { keyOf } from '../indexer.js'
import { hiddenSet, saveHidden } from '../flex.js'

// <img> with gateway-fallback: advance through candidates on error, then
// degrade to a text placeholder. All hosts are https (enforced by CSP img-src).
export function fallbackImg(candidates, attrs = {}) {
  if (!candidates.length) return el('div', { class: 'noimg' }, 'no image')
  let i = 0
  const img = el('img', {
    src: candidates[0], loading: 'lazy', alt: '',
    onerror: () => {
      i += 1
      if (i < candidates.length) img.src = candidates[i]
      else img.replaceWith(el('div', { class: 'noimg' }, 'no image'))
    },
    ...attrs,
  })
  return img
}

export function renderGallery(container, state, onSelect, onUnhide) {
  if (state.scanning) {
    return replace(container,
      el('h2', {}, state.progress || 'Scanning…'),
      el('div', { class: 'grid' }, Array.from({ length: 8 }, () => el('div', { class: 'skel' }))))
  }
  if (!state.nfts.length) {
    return replace(container, el('div', { class: 'empty' },
      'Connect your KeepKey Vault, then scan to see NFTs across your accounts (Ethereum + Base).'))
  }
  const visible = state.nfts.filter((n) => !n.spam && !hiddenSet.has(keyOf(n)))
  const hidden = state.nfts.filter((n) => n.spam || hiddenSet.has(keyOf(n)))
  const byChain = {}
  visible.forEach((n) => (byChain[n.chainName] ||= []).push(n))

  const sections = Object.entries(byChain).flatMap(([chainName, list]) => [
    el('h2', {}, `${chainName} — ${list.length}`),
    el('div', { class: 'grid' }, list.map((n) => {
      const card = el('div', { class: 'card', onclick: () => onSelect(n, card) },
        fallbackImg(n.images),
        el('div', { class: 'meta' },
          el('div', { class: 'nm' }, n.name),
          el('div', { class: 'ch' }, `${chainName} · ${n.standard ?? ''}`)))
      card.dataset.key = keyOf(n)
      return card
    })),
  ])

  let hiddenSection = null
  if (hidden.length) {
    // hidden items render as TEXT ONLY — their images are never fetched
    const list = el('ul', { style: 'display:none' }, hidden.map((n) =>
      el('li', {},
        el('span', {}, `${n.name.slice(0, 60)} · ${n.chainName} · ${n.spam ? 'auto-flagged spam' : 'hidden by you'}`),
        el('button', { class: 'ghost', onclick: () => { hiddenSet.delete(keyOf(n)); saveHidden(); n.spam = false; onUnhide() } }, 'unhide'))))
    hiddenSection = el('div', { id: 'hiddenSection' },
      el('button', {
        class: 'ghost',
        onclick: () => { list.style.display = list.style.display === 'none' ? 'block' : 'none' },
      }, `${hidden.length} hidden (spam + hidden by you) — show`),
      list)
  }
  replace(container, sections, hiddenSection)
}
