// Feature 6: live pendant status card. Polls GET /status (pausing while the
// tab is hidden), matches the displayed token against scanned NFTs for a
// name/thumbnail, offers view + clear.
import { el, replace } from '../dom.js'
import { DEFAULT_PENDANT } from '../config.js'
import { pendantStatus, pendantClear } from '../pendant.js'
import { fmtLeft } from '../flex.js'
import { fallbackImg } from './gallery.js'

export function createPendantCard(getNfts) {
  const box = el('div')
  let timer = null

  const pendantUrl = () => localStorage.getItem('pendant_url') || DEFAULT_PENDANT

  async function tick() {
    let status = null
    try { status = await pendantStatus(pendantUrl()) } catch { /* offline */ }
    render(status)
  }

  function render(status) {
    const now = Math.floor(Date.now() / 1000)
    if (!status) {
      return replace(box, el('div', { class: 'pendcard off' },
        el('span', { class: 'dot' }), `pendant · ${pendantUrl()} · unreachable`))
    }
    if (!status.displaying) {
      return replace(box, el('div', { class: 'pendcard idle' },
        el('span', { class: 'dot' }), 'pendant · idle (KeepKey logo)',
        el('div', { class: 'spacer' }),
        el('button', { class: 'ghost', onclick: () => window.open(pendantUrl(), '_blank', 'noopener') }, 'View')))
    }
    const d = status.displaying
    const match = getNfts().find((n) =>
      n.contract?.toLowerCase() === String(d.nftContract).toLowerCase() && n.tokenId === String(d.tokenId))
    const expired = Number(d.expiresAt) <= now
    return replace(box, el('div', { class: 'pendcard on' },
      match?.images?.length ? fallbackImg(match.images, { class: 'thumb' }) : null,
      el('div', { style: 'flex:1;min-width:0' },
        el('div', { class: 'pt' }, 'Pendant displaying: ',
          el('b', {}, match ? match.name : `${String(d.nftContract).slice(0, 10)}… #${d.tokenId}`)),
        el('div', { class: expired ? 'ps bad' : 'ps' },
          expired ? 'authorization EXPIRED' : `authorization ${fmtLeft(Number(d.expiresAt) - now)}`)),
      el('button', { class: 'ghost', onclick: () => window.open(pendantUrl(), '_blank', 'noopener') }, 'View'),
      el('button', {
        class: 'danger',
        onclick: async (e) => {
          if (!confirm('Clear the pendant display? It returns to the KeepKey logo until the next push.')) return
          e.target.disabled = true
          try { await pendantClear(pendantUrl()); await tick() } catch (err) { alert('clear failed: ' + err.message) }
          e.target.disabled = false
        },
      }, 'Clear')))
  }

  function start() {
    tick()
    timer = setInterval(() => { if (!document.hidden) tick() }, 10000)
    document.addEventListener('visibilitychange', () => { if (!document.hidden) tick() })
  }
  return { box, start, tick }
}
