import './styles.css'
import { el, replace } from './dom.js'
import { ACCOUNT_COUNT, CHAINS } from './config.js'
import { connect, deriveAddress } from './vault.js'
import { scanAll } from './indexer.js'
import { renderGallery } from './ui/gallery.js'
import { renderDetail } from './ui/detail.js'
import { renderProofs } from './ui/proofs.js'
import { renderIdentity } from './ui/identity.js'
import { createPendantCard } from './ui/pendantCard.js'

const state = { connected: false, features: null, accounts: [], nfts: [], sel: null, scanning: false, progress: '' }

const vaultPill = el('span', { class: 'pill' }, 'vault: disconnected')
const connectBtn = el('button', { onclick: onConnect }, 'Connect Vault')
const scanBtn = el('button', { class: 'ghost', disabled: true, onclick: () => scan() }, 'Scan NFTs')
const identityBox = el('div')
const pendantCard = createPendantCard(() => state.nfts)
const proofsBox = el('div')
const galleryBox = el('div')
const detailPane = el('aside', { id: 'detailPane' })

function refresh(clearSel = false) {
  if (clearSel) state.sel = null
  renderIdentity(identityBox, state)
  renderProofs(proofsBox)
  renderGallery(galleryBox, state, onSelect, () => refresh())
  renderDetail(detailPane, state.sel, refresh)
}

function onSelect(n, card) {
  document.querySelectorAll('.card.sel').forEach((c) => c.classList.remove('sel'))
  card.classList.add('sel')
  state.sel = n
  renderDetail(detailPane, n, refresh)
}

async function onConnect() {
  connectBtn.disabled = true
  connectBtn.textContent = 'Approve in Vault…'
  try {
    state.features = await connect()
    state.connected = true
    vaultPill.textContent = 'vault: connected'
    vaultPill.classList.add('on')
    scanBtn.disabled = false
    connectBtn.style.display = 'none'
    scan()
  } catch (e) {
    alert('Vault connection failed: ' + e.message + '\nIs KeepKey Vault running with the API bridge enabled?')
    connectBtn.disabled = false
    connectBtn.textContent = 'Connect Vault'
  }
}

async function scan() {
  scanBtn.disabled = true
  scanBtn.textContent = 'Scanning…'
  state.scanning = true
  state.nfts = []
  let done = 0
  const total = ACCOUNT_COUNT * CHAINS.length
  try {
    state.accounts = []
    for (let i = 0; i < ACCOUNT_COUNT; i++) {
      state.progress = `deriving account ${i + 1}/${ACCOUNT_COUNT}…`
      refresh()
      state.accounts.push({ index: i, address: await deriveAddress(i) })
    }
    state.nfts = await scanAll(state.accounts, () => {
      done += 1
      state.progress = `scanning ${done}/${total} account·chain pairs…`
      refresh()
    })
  } finally {
    state.scanning = false
    state.progress = ''
    scanBtn.disabled = false
    scanBtn.textContent = 'Rescan'
    refresh()
  }
}

replace(document.getElementById('app'),
  el('header', {},
    el('h1', {}, 'KeepKey ', el('span', { style: 'color:var(--gold)' }, 'NFT Gallery')),
    vaultPill,
    identityBox,
    el('div', { class: 'spacer' }),
    connectBtn, scanBtn),
  el('main', {},
    el('section', { id: 'galleryPane' }, pendantCard.box, proofsBox, galleryBox),
    detailPane))

refresh()
pendantCard.start()
if (localStorage.getItem('kk_gallery_key')) onConnect()
