// Proof (flex) store + share URLs. Proof bundles travel in URL fragments —
// never sent to a server by the browser.
import { SHARE_BASE } from './config.js'

export const loadProofs = () => {
  try { return JSON.parse(localStorage.getItem('kk_flexes') || '[]') } catch { return [] }
}

export function saveProof(nft, message, signature) {
  const proofs = loadProofs()
  proofs.unshift({
    name: nft.name, chainName: nft.chainName,
    expiresAt: Number(message.expiresAt),
    bundle: { p: { chainId: nft.chainId, ...message }, s: signature },
  })
  localStorage.setItem('kk_flexes', JSON.stringify(proofs.slice(0, 20)))
}

// prune proofs a day past expiry; keep fresh-expired visible
export function pruneProofs() {
  const now = Math.floor(Date.now() / 1000)
  const proofs = loadProofs().filter((f) => f.expiresAt > now - 86400)
  localStorage.setItem('kk_flexes', JSON.stringify(proofs))
  return proofs
}

export function proofUrl(bundle) {
  const b64 = btoa(JSON.stringify(bundle)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
  return `${SHARE_BASE}/verify.html#${b64}`
}

export const fmtLeft = (secs) => {
  if (secs <= 0) return 'expired'
  if (secs < 3600) return Math.ceil(secs / 60) + 'm left'
  if (secs < 86400) return Math.floor(secs / 3600) + 'h ' + Math.ceil((secs % 3600) / 60) + 'm left'
  return Math.floor(secs / 86400) + 'd ' + Math.floor((secs % 86400) / 3600) + 'h left'
}

const HIDDEN_KEY = 'kk_hidden'
export const hiddenSet = new Set(JSON.parse(localStorage.getItem(HIDDEN_KEY) || '[]'))
export const saveHidden = () => localStorage.setItem(HIDDEN_KEY, JSON.stringify([...hiddenSet]))
