// Feature 5: wallet identity header — which physical device is connected and
// which accounts the gallery is acting for. Making identity visible is a
// security control here: two-device households (like this one) otherwise
// discover mismatches only at signature time.
import { el, replace } from '../dom.js'

export function renderIdentity(container, state) {
  if (!state.connected) return replace(container)
  const label = state.features?.label || 'KeepKey'
  const acct0 = state.accounts[0]?.address

  const pop = el('div', { class: 'idpop', style: 'display:none' },
    el('div', { class: 'idpop-title' }, 'Connected device'),
    el('div', { class: 'idpop-dev' }, label,
      state.features ? ` · fw ${state.features.major_version}.${state.features.minor_version}.${state.features.patch_version}` : ''),
    state.accounts.length
      ? state.accounts.map((a) => el('div', { class: 'idpop-row' },
          el('span', { class: 'idx' }, `#${a.index}`),
          el('code', {}, a.address),
          el('button', {
            class: 'ghost',
            onclick: (e) => { navigator.clipboard.writeText(a.address); e.target.textContent = '✓'; setTimeout(() => { e.target.textContent = 'copy' }, 1200) },
          }, 'copy')))
      : el('div', { class: 'idpop-row' }, 'accounts appear after a scan'))

  const chip = el('button', {
    class: 'idchip',
    onclick: () => { pop.style.display = pop.style.display === 'none' ? 'block' : 'none' },
  }, '🔑 ', label, acct0 ? ` · ${acct0.slice(0, 6)}…${acct0.slice(-4)}` : '')

  replace(container, el('div', { class: 'idwrap' }, chip, pop))
}
