// Pendant device client (mock server today, ESP32 firmware tomorrow —
// identical API per SPEC.md).

const clean = (url) => url.replace(/\/$/, '')

export const pendantPair = async (url) => (await fetch(clean(url) + '/pair')).json()

export const pendantStatus = async (url, timeoutMs = 4000) => {
  const ctl = new AbortController()
  const t = setTimeout(() => ctl.abort(), timeoutMs)
  try {
    return await (await fetch(clean(url) + '/status', { signal: ctl.signal })).json()
  } finally { clearTimeout(t) }
}

export const pendantClear = async (url) =>
  (await fetch(clean(url) + '/clear', { method: 'POST' })).json()

export async function pendantAuthorize(url, payload, signature, imageB64) {
  const r = await fetch(clean(url) + '/authorize', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ payload, signature, image: imageB64 }),
  })
  const out = await r.json().catch(() => ({}))
  if (!r.ok) {
    throw new Error((out.error || r.status) +
      (out.owner ? ` — on-chain owner ${String(out.owner).slice(0, 10)}…, signer ${String(out.signer).slice(0, 10)}…` : ''))
  }
  return out
}

// Center-crop an <img> to a 466×466 JPEG; returns { bytes, b64 }.
export async function renderPendantJpeg(img) {
  if (!img.naturalWidth) throw new Error('image not loaded (or blocked for canvas use)')
  const side = Math.min(img.naturalWidth, img.naturalHeight)
  const canvas = Object.assign(document.createElement('canvas'), { width: 466, height: 466 })
  canvas.getContext('2d').drawImage(img, (img.naturalWidth - side) / 2, (img.naturalHeight - side) / 2, side, side, 0, 0, 466, 466)
  const blob = await new Promise((res) => canvas.toBlob(res, 'image/jpeg', 0.85))
  const bytes = new Uint8Array(await blob.arrayBuffer())
  let bin = ''
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000))
  return { bytes, b64: btoa(bin) }
}
