// KeepKey Vault bridge client (localhost REST). The API key lives in
// localStorage: acceptable because script-src 'self' + zero markup injection
// keep foreign script out of this origin, and every signature still requires
// physical device confirmation regardless.
import { VAULT, HARDENED } from './config.js'

let apiKey = localStorage.getItem('kk_gallery_key')

async function vaultFetch(path, body) {
  const r = await fetch(VAULT + path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...(apiKey ? { Authorization: `Bearer ${apiKey}` } : {}) },
    body: JSON.stringify(body),
  })
  const j = await r.json().catch(() => ({}))
  if (!r.ok) { const e = new Error(j.error || `vault ${r.status}`); e.status = r.status; throw e }
  return j
}

export async function connect() {
  if (!apiKey) {
    const { apiKey: k } = await vaultFetch('/auth/pair', { name: 'KeepKey NFT Gallery' })
    apiKey = k
    localStorage.setItem('kk_gallery_key', k)
  }
  try {
    return await vaultFetch('/system/info/get-features', {})
  } catch (e) {
    if (e.status === 401 || e.status === 403) {   // stale key: re-pair once
      apiKey = null
      localStorage.removeItem('kk_gallery_key')
      return connect()
    }
    throw e
  }
}

export const deriveAddress = async (accountIndex) =>
  (await vaultFetch('/addresses/eth', {
    address_n: [HARDENED + 44, HARDENED + 60, HARDENED + accountIndex, 0, 0],
    show_display: false,
  })).address

export const signTypedData = async (address, typedData) =>
  (await vaultFetch('/eth/sign-typed-data', { address, typedData })).signature
