import { keccak256 } from 'viem'
import { el, replace } from '../dom.js'
import { ZERO32, DEFAULT_PENDANT, chainById, HARDENED } from '../config.js'
import { deriveAddress, signTypedData } from '../vault.js'
import { buildTypedData, digests } from '../eip712.js'
import { saveProof, hiddenSet, saveHidden } from '../flex.js'
import { keyOf } from '../indexer.js'
import { pendantPair, pendantAuthorize, renderPendantJpeg } from '../pendant.js'
import { fallbackImg } from './gallery.js'
import { showQrModal } from './modal.js'

const PUSH_WINDOWS = [[86400, '1 day'], [604800, '7 days'], [2592000, '30 days']]
const FLEX_WINDOWS = [[3600, '1 hour'], [28800, '8 hours'], [86400, '1 day'], [604800, '7 days'], [2592000, '30 days (cannot be revoked)']]

let logEl = null
const log = (msg, cls = '') => {
  if (!logEl) return
  logEl.append(el('div', { class: cls || null }, msg))
  logEl.scrollTop = 1e9
}

// Re-derive the owner account from the live device before any signature —
// catches device swaps between scan-time and sign-time.
async function ownerGuardAndSign(n, message) {
  log('checking connected device is the owner…')
  const liveAddr = await deriveAddress(n.ownerIndex)
  if (liveAddr.toLowerCase() !== n.owner.toLowerCase()) {
    throw new Error(`connected KeepKey is not this NFT's owner — device account ${n.ownerIndex} is ${liveAddr.slice(0, 10)}…, owner is ${n.owner.slice(0, 10)}…. Plug in the right device (or Rescan).`)
  }
  log('device matches owner ' + liveAddr.slice(0, 10) + '…', 'ok')

  const { domainSep, structHash } = digests(n.chainId, message)
  log('── VERIFY ON DEVICE ──', 'act')
  log('domain digest:\n' + domainSep.slice(2), 'act')
  log('message digest:\n' + structHash.slice(2), 'act')
  log('Your KeepKey must show these two hashes. If they differ, REJECT.', 'act')
  log('CONFIRM in Vault, then on your KeepKey…', 'act')
  const signature = await signTypedData(n.owner, buildTypedData(n.chainId, message))
  log('signed ' + signature.slice(0, 18) + '…', 'ok')
  return signature
}

async function push(n, artImg, pendantUrl, windowSecs, refresh) {
  localStorage.setItem('pendant_url', pendantUrl)
  log('pairing with pendant…')
  const pair = await pendantPair(pendantUrl)
  log(`device ${String(pair.deviceId).slice(0, 14)}… nonce issued`, 'ok')

  log('rendering 466×466 JPEG…')
  const { bytes, b64 } = await renderPendantJpeg(artImg)
  const imageHash = keccak256(bytes)
  log(`image ${(bytes.length / 1024).toFixed(0)}KB, keccak ${imageHash.slice(0, 14)}…`, 'ok')

  const now = Math.floor(Date.now() / 1000)
  const message = {
    nftContract: n.contract, tokenId: n.tokenId, deviceId: pair.deviceId, nonce: pair.nonce,
    imageHash, issuedAt: String(now - 60), expiresAt: String(now + windowSecs),
  }
  const signature = await ownerGuardAndSign(n, message)
  log('pushing to pendant (verifies sig + on-chain ownership)…')
  const out = await pendantAuthorize(pendantUrl, { chainId: n.chainId, ...message }, signature, b64)
  log(`PENDANT AUTHORIZED — displaying ${n.name} as ${String(out.signer).slice(0, 10)}…`, 'ok')
  saveProof(n, message, signature)
  refresh()
}

async function flex(n, windowSecs, refresh) {
  const now = Math.floor(Date.now() / 1000)
  const nonce = keccak256(crypto.getRandomValues(new Uint8Array(32)))
  const message = {
    nftContract: n.contract, tokenId: n.tokenId,
    deviceId: ZERO32, nonce, imageHash: ZERO32,
    issuedAt: String(now - 60), expiresAt: String(now + windowSecs),
  }
  log(`broadcast flex for ${n.name}…`)
  const signature = await ownerGuardAndSign(n, message)
  saveProof(n, message, signature)
  log('FLEX SIGNED — QR ready to share anywhere.', 'ok')
  refresh()
  showQrModal({ p: { chainId: n.chainId, ...message }, s: signature })
}

export function renderDetail(container, n, refresh) {
  if (!n) return replace(container, el('div', { class: 'empty' }, 'Select an NFT'))
  const chain = chainById(n.chainId)
  const artImg = fallbackImg(n.images, { class: 'art', crossorigin: 'anonymous' })

  const pendantUrl = el('input', { value: localStorage.getItem('pendant_url') || DEFAULT_PENDANT })
  const pushSel = el('select', {}, PUSH_WINDOWS.map(([v, t], i) => el('option', { value: v, selected: t === '7 days' || null }, t)))
  const flexSel = el('select', {}, FLEX_WINDOWS.map(([v, t]) => el('option', { value: v, selected: t === '1 hour' || null }, t)))

  const guard = (btn, fn) => async () => {
    btn.disabled = true
    try { await fn() } catch (e) { log('failed: ' + e.message, 'err') }
    btn.disabled = false
  }
  const pushBtn = el('button', {}, 'Sign & Push')
  pushBtn.addEventListener('click', guard(pushBtn, () => push(n, artImg, pendantUrl.value, Number(pushSel.value), refresh)))
  const flexBtn = el('button', {}, 'Sign Flex')
  flexBtn.addEventListener('click', guard(flexBtn, async () => {
    if (Number(flexSel.value) === 2592000 &&
        !confirm('30-day proofs CANNOT be revoked before they expire.\n\nThe only early kill is transferring the NFT to a different address (which also cancels marketplace listings and costs gas).\n\nSign a 30-day proof anyway?')) return
    await flex(n, Number(flexSel.value), refresh)
  }))

  logEl = el('div', { id: 'log' })

  replace(container,
    artImg,
    el('div', { style: 'margin-top:14px' },
      el('div', { style: 'font-size:17px;font-weight:700' }, n.name),
      el('div', { class: 'row' }, el('span', {}, 'chain'), el('span', {}, `${n.chainName} (${n.chainId})`)),
      el('div', { class: 'row' }, el('span', {}, 'contract'), el('span', {}, n.contract)),
      el('div', { class: 'row' }, el('span', {}, 'token'), el('span', {}, '#' + n.tokenId)),
      el('div', { class: 'row' }, el('span', {}, 'owner (your account)'), el('span', {}, `${n.owner.slice(0, 10)}… (account ${n.ownerIndex})`))),
    el('div', { class: 'links' },
      el('a', { href: `${chain.explorer}/nft/${n.contract}/${n.tokenId}`, target: '_blank', rel: 'noopener noreferrer' }, `${chain.explorerName} ↗`),
      el('a', { href: `https://opensea.io/assets/${chain.opensea}/${n.contract}/${n.tokenId}`, target: '_blank', rel: 'noopener noreferrer' }, 'OpenSea ↗'),
      el('a', { href: `https://zora.co/collect/${chain.zora}:${n.contract}/${n.tokenId}`, target: '_blank', rel: 'noopener noreferrer' }, 'Zora ↗'),
      n.images[0] && el('a', { href: n.images[0], target: '_blank', rel: 'noopener noreferrer' }, 'Raw image ↗')),
    el('div', { class: 'traits' }, (n.attributes || [])
      .filter((a) => a && (a.trait_type || a.value !== undefined))
      .map((a) => el('span', { class: 'trait' },
        el('b', {}, String(a.trait_type || 'trait').slice(0, 24)),
        String(a.value ?? '').slice(0, 32)))),
    el('div', { class: 'pushbox' },
      el('div', { class: 'boxtitle' }, 'Push to pendant'),
      el('label', {}, 'pendant address'), pendantUrl,
      el('label', {}, 'authorization window'), pushSel,
      el('div', { class: 'btnrow' }, pushBtn,
        el('button', { class: 'ghost', onclick: () => window.open(pendantUrl.value, '_blank', 'noopener') }, 'View pendant')),
      el('div', { class: 'divider' },
        el('div', { class: 'boxtitle' }, 'Broadcast flex ', el('span', { class: 'boxsub' }, '— shareable proof, no pendant needed')),
        el('label', {}, 'proof valid for'), flexSel,
        el('div', { class: 'btnrow' }, flexBtn)),
      logEl),
    el('button', {
      class: 'danger hidebtn',
      onclick: () => {
        if (!confirm(`Hide "${n.name}" from this gallery permanently?\n\n(It stays in your wallet on-chain — nothing can remove it from the blockchain — but this browser will never show it again unless you unhide it.)`)) return
        hiddenSet.add(keyOf(n)); saveHidden(); refresh(true)
      },
    }, 'Hide this NFT forever (this browser)'))
}
